using System.Windows;
using System.Windows.Automation;
using System.Windows.Automation.Peers;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Input;
using System.Windows.Media;
using Humcp.Core;
using Humcp.Schema;

namespace Humcp.App;

/// <summary>
/// A question a server stopped in the middle of a tool call to ask, and the window that answers it
/// (ROADMAP §10, Phase 5).
/// </summary>
/// <remarks>
/// <para>
/// The form is generated by the same <see cref="FormBuilder"/>, bound to the same templates and
/// filled in through the same <see cref="FormState"/> as a tool's own parameters, because an
/// elicitation schema is a restricted subset of the same JSON Schema — §3's claim, and phase5-notes
/// 3.2 is the measurement that says the subset really does land wholly at Tier 1. There is no
/// second form generator here and there is not meant to be one.
/// </para>
/// <para>
/// <b>Nothing on this form is hidden</b>, which is the one place it departs from a tool form. A
/// tool form starts with its optional parameters collapsed (§4, pitfall 4), and what makes that
/// safe is that an untouched field is not sent (§5). That is not true here: the client SDK puts
/// every schema-stated <c>default</c> back into the answer on its way to the wire, so a field the
/// user never saw is a field the server is told they agreed to (phase5-notes 3.3). Showing
/// everything is the only version of this window that does not misreport what the user did.
/// </para>
/// <para>
/// Non-modal like every other window humcp opens (§8), and the call it belongs to is waiting on it,
/// so every way out of it answers: <kbd>Escape</kbd>, <kbd>Ctrl</kbd>+<kbd>W</kbd>, the Cancel
/// button and the title bar all cancel, and closing without choosing is cancelling rather than
/// nothing at all.
/// </para>
/// </remarks>
internal sealed class ElicitationWindow : Window
{
    private readonly ElicitationRequest _request;
    private readonly FormState? _state;
    private readonly WindowManager _windows;
    private readonly TaskCompletionSource<ElicitationAnswer> _answered = new();

    private readonly FormItemsControl _fields = new();
    private readonly ListBox _problems = new();
    private readonly DockPanel _problemsPane = new();
    private readonly TextBlock _problemsHeading = new();
    private readonly TextBlock _status = new();

    /// <summary>The server's own message, and where the caret starts (§7.28).</summary>
    private TextBox? _messageBox;

    private string? _warnedAbout;

    private ElicitationWindow(
        Window owner, string title, ElicitationRequest request, WindowManager windows)
    {
        _request = request;
        _windows = windows;
        _state = request.HasFields
            ? FormState.Create(request.Form, AccessKeys.QuestionCommands)
            : null;

        Title = title;
        Owner = owner;
        Width = 660;
        Height = request.HasFields ? 620 : 380;
        MinWidth = 460;
        WindowStartupLocation = WindowStartupLocation.CenterOwner;

        // §7.17: a WPF Window is a ContentControl, and with no name of its own it announces the
        // whole of its content as its name.
        AutomationProperties.SetName(this, title);

        DataContext = _state;
        Content = Build();

        _windows.Track(this);

        Bind();

        Loaded += (_, _) => Opened();
        Closed += (_, _) => _answered.TrySetResult(ElicitationAnswer.Cancelled);
    }

    /// <summary>
    /// Shows the question and waits for the answer. Called from whatever thread the SDK resolved an
    /// input request on, which is never the UI thread.
    /// </summary>
    /// <remarks>
    /// The cancellation token is the tool call's own, so closing the window the call was made from
    /// takes this one with it — and answers, because a call waiting on a window that no longer
    /// exists is a call that never comes back.
    /// </remarks>
    public static async Task<ElicitationAnswer> AskAsync(
        Window owner,
        string title,
        ElicitationRequest request,
        WindowManager windows,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(owner);
        ArgumentNullException.ThrowIfNull(request);
        ArgumentNullException.ThrowIfNull(windows);

        var window = await owner.Dispatcher.InvokeAsync(() =>
        {
            var created = new ElicitationWindow(owner, title, request, windows);
            created.Show();
            WindowManager.Activate(created);
            return created;
        });

        await using var closing = cancellationToken.Register(
            () => window.Dispatcher.BeginInvoke(window.Close));

        return await window._answered.Task.ConfigureAwait(false);
    }

    // ------------------------------------------------------------------ the window

    private UIElement Build()
    {
        var layout = new DockPanel();

        var question = new MenuItem { Header = "_Question" };
        question.Items.Add(Item("_Accept", ElicitationCommands.Accept, "Ctrl+Enter"));
        question.Items.Add(Item("_Decline", ElicitationCommands.Decline, ""));
        question.Items.Add(Item("_Cancel", WindowManager.CloseWindow, "Esc"));
        question.Items.Add(new Separator());
        question.Items.Add(Item("Detai_ls of this field", FormCommands.Details, "F1"));

        var bar = _windows.CreateMenuBar(this, closable: true, question);
        DockPanel.SetDock(bar, Dock.Top);
        layout.Children.Add(bar);

        var top = new StackPanel { Margin = new Thickness(10, 10, 10, 6) };
        DockPanel.SetDock(top, Dock.Top);

        // §7.28: a heading is on screen and in nobody's ear, and the message is the whole reason
        // this window exists. It goes in a read-only, caret-navigable box (§7.9) so it can be
        // reviewed a line at a time — it is untrusted server text and may be long.
        top.Children.Add(ReadOnlyBox("What the server is asking",
            _request.Message.Length > 0 ? _request.Message : "(the server did not say)",
            "This is the server's own wording.",
            out var messageBox));

        // Every id here is prefixed, because an owned window is a UIA descendant of its owner and
        // an id shared between two of them makes every lookup a coin toss (§9, phase3-notes 4.3).
        AutomationProperties.SetAutomationId(messageBox, "QuestionMessage");
        _messageBox = messageBox;

        if (_request.Kind == ElicitationKind.WebPage)
        {
            // One short sentence, because a wrapped read-only box is read to the end of its first
            // *visual* line on focus and no further — so a three-sentence explanation was heard as
            // a sentence and a half, cut mid-clause (phase5-notes 4.7).
            top.Children.Add(ReadOnlyBox("What humcp will do about it",
                "humcp does not open web pages during a tool call. Decline or Cancel.",
                "",
                out _));

            // An address is one line by nature, and wrapping it is what would split it across two.
            top.Children.Add(ReadOnlyBox("Address",
                _request.Url is { Length: > 0 } url ? url : "(the server did not give one)",
                "humcp will not open this. Control plus C copies it.",
                out var addressBox,
                wrap: false));

            AutomationProperties.SetAutomationId(addressBox, "QuestionUrl");
        }

        layout.Children.Add(top);

        // Focusable false for the same reason a scroll viewer is (§7.14): a status bar is a place to
        // put a message, not a control, and WPF reports one as keyboard-focusable to UI Automation
        // whether or not Tab ever reaches it.
        var statusBar = new StatusBar { Focusable = false, IsTabStop = false };
        DockPanel.SetDock(statusBar, Dock.Bottom);

        // A polite live region with no name of its own: a TextBlock's accessible name is its text,
        // so naming it would make every announcement say the label instead of the message (§7.16).
        _status.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(_status, "QuestionStatus");
        AutomationProperties.SetLiveSetting(_status, AutomationLiveSetting.Polite);
        statusBar.Items.Add(new StatusBarItem { Content = _status });
        layout.Children.Add(statusBar);

        var body = new Grid { Margin = new Thickness(10, 0, 10, 0) };
        body.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        body.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        body.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

        body.Children.Add(Fields());
        body.Children.Add(Problems());
        body.Children.Add(Buttons());

        layout.Children.Add(body);
        return layout;
    }

    private UIElement Fields()
    {
        var pane = new DockPanel();
        Grid.SetRow(pane, 0);

        if (_state is null)
        {
            // A question with nothing to fill in is not an empty form, it is a question. Saying so
            // where a field list would have been is better than a silent gap.
            var nothing = new TextBlock
            {
                Text = "There is nothing to fill in. Answer with one of the buttons below.",
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 4, 0, 0),
            };

            pane.Children.Add(nothing);
            return pane;
        }

        var heading = new TextBlock
        {
            Text = $"Answer — {Count(_state.Fields.Count, "field", "fields")}, {_state.RequiredCount} required",
            FontWeight = FontWeights.Bold,
            Margin = new Thickness(0, 0, 0, 6),
        };

        AutomationProperties.SetHeadingLevel(heading, AutomationHeadingLevel.Level2);
        DockPanel.SetDock(heading, Dock.Top);
        pane.Children.Add(heading);

        _fields.ItemsSource = _state.Fields;
        _fields.ItemTemplateSelector = new FieldTemplateSelector();
        AutomationProperties.SetName(_fields, "Answer");
        AutomationProperties.SetAutomationId(_fields, "QuestionFields");

        // Focusable false, like every other scroll viewer here: WPF makes one a tab stop the moment
        // it has something to scroll, and a scroll viewer is not a control (§7.14).
        pane.Children.Add(new ScrollViewer
        {
            Content = _fields,
            Focusable = false,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            Padding = new Thickness(0, 0, 12, 0),
        });

        return pane;
    }

    private UIElement Problems()
    {
        Grid.SetRow(_problemsPane, 1);
        _problemsPane.Visibility = Visibility.Collapsed;
        _problemsPane.Margin = new Thickness(0, 8, 0, 0);

        _problemsHeading.Text = "Problems";
        _problemsHeading.FontWeight = FontWeights.Bold;
        _problemsHeading.Margin = new Thickness(0, 0, 0, 4);
        AutomationProperties.SetHeadingLevel(_problemsHeading, AutomationHeadingLevel.Level2);
        DockPanel.SetDock(_problemsHeading, Dock.Top);
        _problemsPane.Children.Add(_problemsHeading);

        _problems.MaxHeight = 110;
        AutomationProperties.SetName(_problems, "Problems");
        AutomationProperties.SetAutomationId(_problems, "QuestionProblems");
        AutomationProperties.SetHelpText(_problems,
            "Arrow through the problems. Enter moves to the field one is about.");

        _problems.InputBindings.Add(new KeyBinding(FormCommands.GoToProblem, new KeyGesture(Key.Enter))
        {
            CommandParameter = _problems,
        });

        _problemsPane.Children.Add(_problems);
        return _problemsPane;
    }

    private UIElement Buttons()
    {
        var row = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Margin = new Thickness(0, 10, 0, 8),
        };

        Grid.SetRow(row, 2);

        if (_request.Kind == ElicitationKind.Form)
        {
            row.Children.Add(Button("QuestionAccept", "_Accept", ElicitationCommands.Accept, "Control plus Enter",
                _state is null
                    ? "Tells the tool yes, and lets it carry on."
                    : "Sends what is on this form and lets the tool carry on. Control plus Enter does the same."));
        }

        row.Children.Add(Button("QuestionDecline", "_Decline", ElicitationCommands.Decline, "",
            "Tells the tool you will not answer this. The tool decides what to do next."));

        row.Children.Add(Button("QuestionCancel", "_Cancel", WindowManager.CloseWindow, "Escape",
            "Dismisses this question without answering it. Escape and closing the window do the same."));

        return row;
    }

    private static MenuItem Item(string header, RoutedUICommand command, string gesture)
        => new() { Header = header, Command = command, InputGestureText = gesture };

    private static Button Button(
        string id, string content, RoutedUICommand command, string accelerator, string help)
    {
        var button = new Button
        {
            Content = content,
            Command = command,
            Padding = new Thickness(14, 4, 14, 4),
            Margin = new Thickness(0, 0, 8, 0),
        };

        AutomationProperties.SetAutomationId(button, id);

        // Set here rather than left to WPF, which would announce the command's own Text in the slot
        // a screen reader uses for the shortcut (§7.27), and spelled out because it is spoken
        // (§7.15).
        if (accelerator.Length > 0) AutomationProperties.SetAcceleratorKey(button, accelerator);
        AutomationProperties.SetHelpText(button, help);

        return button;
    }

    /// <summary>
    /// One piece of text the user has to be able to read rather than merely see: read-only, with a
    /// caret, a name and a label (§7.9, §7.28).
    /// </summary>
    private static UIElement ReadOnlyBox(
        string label, string text, string help, out TextBox box, bool wrap = true)
    {
        var panel = new StackPanel { Margin = new Thickness(0, 0, 0, 8) };

        var caption = new TextBlock
        {
            Text = label,
            FontWeight = FontWeights.Bold,
            Margin = new Thickness(0, 0, 0, 2),
        };

        AutomationProperties.SetHeadingLevel(caption, AutomationHeadingLevel.Level2);

        box = new TextBox
        {
            Text = text,
            IsReadOnly = true,
            IsReadOnlyCaretVisible = true,
            AcceptsReturn = wrap,
            TextWrapping = wrap ? TextWrapping.Wrap : TextWrapping.NoWrap,
            MaxHeight = 120,
            VerticalScrollBarVisibility = wrap ? ScrollBarVisibility.Auto : ScrollBarVisibility.Disabled,
            HorizontalScrollBarVisibility = wrap ? ScrollBarVisibility.Disabled : ScrollBarVisibility.Auto,
        };

        AutomationProperties.SetName(box, label);
        AutomationProperties.SetLabeledBy(box, caption);

        // Deliberately not "Read only. …": the reader announces that state from the control, and
        // saying it again in help text is the same word twice (phase5-notes 4.1).
        if (help.Length > 0) AutomationProperties.SetHelpText(box, help);

        panel.Children.Add(caption);
        panel.Children.Add(box);
        return panel;
    }

    // ------------------------------------------------------------------ answering

    private void Bind()
    {
        CommandBindings.Add(new CommandBinding(ElicitationCommands.Accept, (_, _) => Accept(),
            (_, e) => e.CanExecute = _request.Kind == ElicitationKind.Form));

        CommandBindings.Add(new CommandBinding(ElicitationCommands.Decline, (_, _) =>
            Answer(ElicitationAnswer.Declined)));

        CommandBindings.Add(new CommandBinding(FormCommands.Details, (_, _) => ShowDetails()));

        // The commands this window's own field templates raise. Without them a multi-select
        // enumeration — and the elicitation subset has two kinds — can be chosen from and never
        // added to, because a command with no binding is a button that is disabled and therefore
        // not even in the tab order (phase5-notes 4.9).
        FormCommandBindings.Attach(this, _state?.Fields ?? [], SetStatus, _windows);

        CommandBindings.Add(new CommandBinding(FormCommands.GoToProblem, (_, e) =>
        {
            if (e.Parameter is ListBox { SelectedItem: ProblemEntry problem }) GoTo(problem);
        }, (_, e) => e.CanExecute = e.Parameter is ListBox { SelectedItem: ProblemEntry }));

        // Ctrl+Enter has to be taken before the focused control sees it: a WPF Button handles Enter
        // itself without looking at the modifiers, so Ctrl+Enter while standing on one of a list's
        // own buttons pressed that button instead (phase3-notes 4.7).
        PreviewKeyDown += (_, e) =>
        {
            if (e.Key is not (Key.Enter or Key.Return)) return;
            if ((Keyboard.Modifiers & ModifierKeys.Control) != ModifierKeys.Control) return;
            if (_request.Kind != ElicitationKind.Form) return;

            e.Handled = true;
            Accept();
        };
    }

    private void Accept()
    {
        if (_state is null)
        {
            Answer(ElicitationAnswer.Accepted([]));
            return;
        }

        var submission = _state.Prepare();
        ShowProblems(submission);

        // The only refusal, and the same one a tool form makes: text that is not JSON is not an
        // answer that can be constructed at all, which is a different thing from an answer we
        // suspect the server will decline (§5).
        if (!submission.CanSend)
        {
            var problem = submission.Build.Problems[0];
            SetStatus($"{problem.Label}: {problem.Message}");
            Focus(_state.Find(problem.FieldPath));
            return;
        }

        if (submission.HasIssues && Signature(submission) is { } signature && signature != _warnedAbout)
        {
            // Warn once, then do as you are told (§5). Client-side validation is advice here for
            // exactly the reason it is advice on a tool form: the server is the authority, and an
            // over-strict client makes a working server unusable.
            _warnedAbout = signature;

            SetStatus($"{Count(submission.Report.Issues.Count, "problem", "problems")} found. " +
                      $"{_state.LeadProblem(submission)} " +
                      "Press Control plus Enter again to answer anyway.");

            Focus(_state.FirstProblem);
            return;
        }

        Answer(ElicitationAnswer.Accepted(submission.Arguments));
    }

    /// <summary>
    /// Answers, then closes. The order matters: <c>Closed</c> cancels if nothing has been said yet,
    /// and <see cref="TaskCompletionSource{T}.TrySetResult"/> keeps the first answer given.
    /// </summary>
    private void Answer(ElicitationAnswer answer)
    {
        _answered.TrySetResult(answer);
        Close();
    }

    private static string Signature(FormSubmission submission) =>
        string.Join("", submission.Report.Issues.Select(i => $"{i.FieldPath}:{i.Message}"));

    private void ShowProblems(FormSubmission submission)
    {
        var entries = new List<ProblemEntry>();

        foreach (var problem in submission.Build.Problems)
            entries.Add(new ProblemEntry($"{problem.Label}: {problem.Message}", problem.FieldPath));

        foreach (var issue in submission.Report.Issues)
            entries.Add(new ProblemEntry(issue.Announcement, issue.FieldPath));

        _problems.ItemsSource = entries;
        _problemsPane.Visibility = entries.Count == 0 ? Visibility.Collapsed : Visibility.Visible;
        _problemsHeading.Text = $"Problems — {entries.Count}";
    }

    private void GoTo(ProblemEntry problem)
    {
        if (_state is not null && Focus(_state.Find(problem.FieldPath))) return;

        SetStatus("That problem is not about a field on this form.");
    }

    // ------------------------------------------------------------------ announcements and focus

    private void Opened()
    {
        SetStatus(Opening());

        // Focus starts on the message rather than on the first field. What the server is asking is
        // the only thing on this window that cannot be worked out from anything else, and a form
        // whose question was never read is a form filled in blind (§7.28).
        _messageBox?.Focus();
    }

    private string Opening()
    {
        if (_request.Kind == ElicitationKind.WebPage)
            return "The tool asked to send you to a web page. humcp does not do that, so this can only be declined or cancelled.";

        if (_state is null)
            return "The tool is asking a question. Accept, Decline or Cancel.";

        return $"The tool needs more information. {Count(_state.Fields.Count, "field", "fields")}, " +
               $"{_state.RequiredCount} required. Control plus Enter answers.";
    }

    private bool Focus(FieldState? field)
    {
        if (field is null) return false;

        _fields.UpdateLayout();

        var wanted = field.SelfAndDescendants().ToHashSet();

        foreach (var element in Descendants(_fields))
        {
            if (element is not Control { Focusable: true, IsEnabled: true, Visibility: Visibility.Visible } control)
                continue;

            if (control.DataContext is not FieldState carried || !wanted.Contains(carried)) continue;

            control.BringIntoView();
            control.Focus();
            return true;
        }

        return false;
    }

    private static IEnumerable<DependencyObject> Descendants(DependencyObject root)
    {
        var count = VisualTreeHelper.GetChildrenCount(root);

        for (var i = 0; i < count; i++)
        {
            var child = VisualTreeHelper.GetChild(root, i);

            yield return child;

            foreach (var descendant in Descendants(child)) yield return descendant;
        }
    }

    private void ShowDetails()
    {
        if ((Keyboard.FocusedElement as FrameworkElement)?.DataContext is FieldState field)
        {
            TextWindow.Show(this, $"Details: {field.Label}", FieldDetails.Describe(field), _windows);
            return;
        }

        TextWindow.Show(this, "Details: this question", Details(), _windows);
    }

    private string Details() => string.Join(Environment.NewLine,
        Title,
        new string('-', 60),
        $"Kind:   {(_request.Kind == ElicitationKind.WebPage ? "an out-of-band web page" : "a form")}",
        $"Fields: {_request.Form.Fields.Count}",
        _request.Url is { Length: > 0 } url ? $"Address: {url}" : "",
        "",
        "Message",
        _request.Message.Length > 0 ? _request.Message : "(the server supplied none)",
        "",
        "Requested schema",
        FieldDetails.Pretty(_request.Form.Schema));

    private void SetStatus(string text)
    {
        LiveRegion.Say(_status, text);
    }

    private static string Count(int count, string singular, string plural) =>
        $"{count} {(count == 1 ? singular : plural)}";
}
